final class METPurchLineBackOrderListPage_Extension
{
}

Method.Source:
/// <summary>
/// Initialize the form.
/// </summary>
public void init()
{
    ItemId                  itemId;
    FormRun                 callerForm = this.args().caller() as FormRun;
    METItemInquiryHelper    helper;

    next init();

    if (this.args().parmObject())
    {
        helper = this.args().parmObject();
        itemId = helper.parmItemId();

        if (itemid)
        {
            OrderType.selection(PurchLineDeliveryType::All);
        }
    }
}
